//! The RTL8822C's register tables (upstream `rtw8822c_table.c`), generated by
//! `tools/wifi/gen_rtw88_tables.py` into the `gen_*` files, and the
//! `rtw_rfe_def` choice of power tables per RFE type (`rtw8822c_rfe_defs`).
//!
//! The word tables keep upstream's condition headers in place; [`crate::phy::cond`]
//! evaluates them while loading, exactly as `rtw_parse_tbl_phy_cond` does. In the
//! binary the statics take about 400 KiB, almost all of it the two RF tables
//! (one branch per cut/RFE combination Realtek ships).

mod gen_bb;
mod gen_dpk;
mod gen_rf_a;
mod gen_rf_b;
mod gen_txpwr;

pub use gen_bb::{AGC, BB, CAL_INIT, MAC};
pub use gen_dpk::{DPK_AFE_IS_DPK, DPK_AFE_NO_DPK, DPK_MAC_BB};
pub use gen_rf_a::RF_A;
pub use gen_rf_b::RF_B;
pub use gen_txpwr::{BB_PG_TYPE0, TXPWR_LMT_TYPE0, TXPWR_LMT_TYPE5};

use crate::dev::{RF_PATH_A, RF_PATH_B};

/// What one RF path loads: upstream's `rf_tbl[]` is `{rf_b, rf_a}`, so path
/// index 0 loads the table declared for path B (and writes path B) first,
/// then index 1 loads path A's. [`crate::phy::cond::load_tables`] keeps that
/// order; each table writes the path it was declared for.
pub const RF_TABLES: [(usize, &[u32]); 2] = [(RF_PATH_B, RF_B), (RF_PATH_A, RF_A)];

/// The power tables one RFE type uses (upstream `struct rtw_rfe_def`; the
/// power-tracking table is type 0 for every 8822C RFE type and lives in
/// [`crate::rtw8822c::pwrtrack`]).
#[derive(Clone, Copy, Debug)]
pub struct RfeDef {
    pub phy_pg: &'static [[u32; 6]],
    pub txpwr_lmt: &'static [[u8; 6]],
}

const TYPE0: RfeDef = RfeDef { phy_pg: BB_PG_TYPE0, txpwr_lmt: TXPWR_LMT_TYPE0 };
const TYPE5: RfeDef = RfeDef { phy_pg: BB_PG_TYPE0, txpwr_lmt: TXPWR_LMT_TYPE5 };

/// Upstream `rtw8822c_rfe_defs`: RFE types 0 to 6, all on by-rate table 0,
/// type 5 with its own limit table.
pub const RFE_DEFS: [RfeDef; 7] = [TYPE0, TYPE0, TYPE0, TYPE0, TYPE0, TYPE5, TYPE0];

/// Upstream `rtw_get_rfe_def`: `None` for an RFE type the driver does not
/// know (upstream refuses such a card in `rtw_check_supported_rfe`).
pub fn rfe_def(rfe_option: u8) -> Option<&'static RfeDef> {
    RFE_DEFS.get(usize::from(rfe_option))
}
